function atlasChoose(){let content=heading('ATLAS / 方案选择','先看条件，再选刷法','七套是不同刷取目标，不是七个成长阶段。配套正文与七条原页已对照，不作收益、价格或难度排名。',false,routeLink('atlas-starter','新手开荒 '+icon('arrow',14),'btn'));
 content+=`<div class="record-banner"><strong>7 套原页已核对 · 8 条正文配法</strong><span>补入图下要求与大师名称；原页更新2026-09-10。深渊稀有怪仍分Jado / Hilda。</span></div>`;
 content+=sec('choose-how','01','按你的目标筛选',`<div class="panel choice-guidance"><div class="priority-row"><b>还在解锁</b><span>先看${routeLink('atlas-starter','新手开荒（Lazy Exile）')}；开荒路线和这七套成型刷法分开。记录没有给出统一人物等级或伤害门槛。</span></div><div class="priority-row"><b>想少挑词缀</b><span>${routeLink('atlas/deli-rush','迷雾 · 速刷')}正文允许三张碑牌炼金后直接用、六词图不追具体属性；能否稳定击杀地图Boss仍需你实际判断。</span></div><div class="priority-row"><b>想刷深渊</b><span>${routeLink('atlas/currency-abyss','通货深渊')}关注坑奖励概率；${routeLink('atlas/abyss-rares','稀有怪深渊')}有两条配法，不是前者的自动升级版。</span></div><div class="priority-row"><b>目标很明确</b><span>先祖秘藏看符文经营，仪式看刷新与减耗，裂隙看城市200%配套，血脉宝石先核对森林50%必选，再处理首轮数量歧义。</span></div></div><div class="caption">以上是依据各份记录作的阅读引导，不是 Fubgun 指定的新手先后顺序，也不保证哪套收益更高。</div>`,'',true);
 content+=note('<strong>0.5.5采购校注：</strong>裂隙碑牌of the Invasion基础范围已从1–3改为1–2；深渊稀有怪制图预兆需Chaos Orb触发，不能直接靠腐化。'+routeLink('learn/mechanisms','看版本校注'),true);
 content+=sec('choose-compare','02','七套配套对照',atlasChoiceTable(),'<p>点方案名称进入同名加点图与正文</p>');
 content+=sec('choose-test','03','采用前，确认四件事',`<div class="panel choice-guidance"><div class="priority-row"><b>关键条件</b><span>对应玩法与大师已解锁，能满足记录列出的硬条件。未写的门槛不是“没有门槛”。</span></div><div class="priority-row"><b>材料准备</b><span>确认碑牌种类、数量与必须词缀；“可替代”不自动代表更便宜。</span></div><div class="priority-row"><b>实际完成</b><span>先按自己能承担的投入试运行；频繁死亡或无法完成目标，不按名字硬套成型刷法。</span></div><div class="priority-row"><b>独立比较</b><span>成本用自己实际购买价，奖励看自己能用或实际售出的部分。该批记录不含同条件收益对照。</span></div></div><div class="caption">本节为使用建议。没有以当前行情更新作者的历史价值判断；不新增人物 Early 加点要求。</div>`);
 return content+footer();}
function currentRuleNote(id){const r=D.currentRuleNotes?.[id];if(!r)return '';return `<div class="current-rule-note"><span class="tag gold">官方0.5.5／前置规则</span><strong>${esc(r.title)}</strong><p>${esc(r.body)}</p>${learnedSources(r.sources)}<div>${routeLink('learn/mechanisms','查看材料流程与版本校注','text-link')}</div></div>`;}
function atlasPage(id){const v=D.variants.find(v=>v.id===id)||D.variants[0],r=D.atlasRecords[v.id],s=r.summary;state.variant=v.id;setStore('variant',v.id);
 let content=heading('ATLAS / 异界与刷图',esc(v.zh),`${esc(v.name)} · 同名原图、配套正文与作者减配条件。`,false,routeLink('atlas-choose','怎么选择方案 '+icon('arrow',14),'btn'))+variantsNav(v.id);
 content+=currentRuleNote(v.id);
 content+=`<div class="record-banner"><strong>本套原页已复核</strong><span>2026-09-29 · 正文、图下说明、大师名称分开核对</span></div><div class="panel summary-panel"><div><span>地图条件</span><strong>${esc(s.map)}</strong></div><div><span>碑牌组合</span><strong>${esc(s.tablets)}</strong></div><div><span>大师配置</span><strong>${esc(s.masters)}</strong></div></div><div class="record-selection"><b>何时研究这套</b><p>${esc(s.selection)}</p><small>选型提示为本站依据记录整理，不是作者顺序。</small></div>${note(esc(s.warning),true)}`;
 let main=sec('atlas-tree','01','异界加点图',primaryTreeNote(r)+`<div class="atlas-image-panel"><div class="image-toolbar"><span class="caption-label"><span class="dot"></span>${esc(v.name)}</span><div class="actions">${[['tree','完整树'],['main','主树'],['side','玩法树']].map(([x,n])=>`<button class="btn small" data-image-view="${x}" aria-pressed="${state.view===x}">${n}</button>`).join('')}<button class="btn small" data-open-image="${v.id}" data-original="true">${icon('expand',12)}原图</button></div></div><div class="image-stage" data-open-image="${v.id}" tabindex="0" role="button" aria-label="放大当前方案加点图"><img id="atlas-tree-image" src="${v.views[state.view]||v.views.tree}" alt="Fubgun ${esc(v.name)} 异界加点原图裁切"></div><div class="image-bottom"><span>保留原图亮暗、连线与图标 · 点击放大</span><span>截图，不是节点导出</span></div></div><div class="caption">图片沿用用户前次提供的同名截图；正文来自本次记录。没有把两者自动认定为同一时刻快照，也没有补出未展开的节点文字。</div>`,'',true);
 main+=sec('atlas-masters','02','大师与选项 · 图示与正文分开',primaryMasterTable(r)+expand('正文强调项与原有表述',caseBlocks(r,'masters'))+expand('历史截图与既有效果词典',`<p class="small muted">下面保留R26—R29的截图和效果词典，名称缺项以上方本轮图示核对为准。既有词典不是本轮机制验证，原图空位仍保留。</p>${masterGroups(v)}`),recordSourceLink(r));
 main+=sec('atlas-setup','03','地图、碑牌与关键词缀',currentRuleNote(v.id)+r.cases.map(c=>`<div class="record-case">${r.cases.length>1?`<h3 class="case-heading">${esc(c.label)} <span class="tag gray">独立配法</span></h3>`:''}<h4 class="record-subhead">地图要求</h4>${recordBlock(c.sections.map)}<h4 class="record-subhead">碑牌种类与数量</h4>${recordBlock(c.sections.tablets)}<h4 class="record-subhead">关键词缀</h4>${recordBlock(c.sections.mods)}</div>`).join(''),recordSourceLink(r));
 main+=sec('atlas-play','04','作者写明的操作与结束条件',caseBlocks(r,'play'),recordSourceLink(r));
 main+=sec('atlas-budget','05','减配、替代与适用条件',caseBlocks(r,'budget')+note('替代配置不等于便宜配置。历史价值判断不按当前报价使用；原文未说明的数量、门槛和步骤不会从别的方案补入。'),recordSourceLink(r));
 main+=sec('atlas-source','06','来源与记录边界',`<div class="panel panel-inner record-source"><p><b>本轮原页核对：</b>2026-09-29；页面显示更新 ${esc(r.page_updated)}。按本方案URL读取配套正文、图下说明和图标名称，不含评论区。</p><p><b>中文主体与历史记录：</b>${esc(r.filename)} · ${esc(r.read_time)}。上传原文原样保留；本轮新增内容以上方明确标注为准。</p><p>已核对可读文字不等于导出全部动态节点。没有重新绘制旧图、补造节点ID或验收当前游戏效果；原文未说明项和数量歧义继续保留。</p><div class="actions">${safeLink(r.primary.url,'作者同名方案')}<button class="btn small" data-download-atlas-record="${v.id}">下载原上传读取记录</button>${routeLink('atlas-choose','七套条件对照 '+icon('arrow',12),'text-link')}</div></div>`+expand('展开原上传记录（历史中文归纳，不回写）',`<pre class="source-text">${esc(r.raw_markdown)}</pre>`));
 return content+`<div class="content-with-toc"><div>${main}</div>${toc([['atlas-tree','01','同名加点图'],['atlas-masters','02','大师配置'],['atlas-setup','03','地图与碑牌'],['atlas-play','04','操作顺序'],['atlas-budget','05','减配与替代'],['atlas-source','06','来源记录']])}</div>`+footer();}
function downloadAtlasRecord(id){const r=D.atlasRecords[id];if(!r)return;const u=URL.createObjectURL(new Blob([r.raw_markdown],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}

function learnedSources(ids){return ids.length?`<div class="learning-citations">依据：${ids.map(id=>{const s=D.learningSources[id];return s?safeLink(s.url,esc(id)+' · '+esc(s.kind)) : esc(id)}).join('　')}</div>`:''}
function learningPage(id){if(id==='ascendancy')return ascendancyChinese();const q=D.learningPages[id]||D.learningPages.audit;
 let body=heading('学习 / '+(q.group==='character'?'人物成长':q.group==='atlas'?'玩法规则':'内容与成长'),q.title,q.description,false,routeLink('learn/audit-beginner','新手复查','btn small'));
 let main='';
 if(id==='ascendancy')main+=`<div class="ascendancy-picker panel panel-inner"><div><strong>你已经获得多少升华点？</strong><div class="small muted">已分配＋未分配的总数；这里只作手动定位，不读取角色。</div></div><div class="actions" role="group" aria-label="已获得升华点">${[0,2,4,6,8].map(n=>`<button class="btn small" data-earned="${n}" aria-pressed="${getStore('earned-ascendancy','0')===String(n)}">${n} 点</button>`).join('')}</div><p id="ascendancy-next" role="status"></p></div>`;
 main+=q.sections.map((s,i)=>sec('learn-'+q.id+'-'+i,String(i+1).padStart(2,'0'),esc(s.title),`<div class="learning-body">${s.html}</div>${['sekhemas','chaos'].includes(id)?expand('查看这部分的依据',learnedSources(s.sources)):learnedSources(s.sources)}`,s.kind==='规则补充'?'':`<p class="learning-kind">${esc(s.kind)}</p>`,i===0)).join('');
 main+=`<div class="learning-end"><strong>相关内容</strong><div class="actions">${(q.related?q.related.map(k=>D.learningPages[k]).filter(Boolean):Object.values(D.learningPages).filter(x=>x.id!==q.id&&x.id!=='audit').slice(0,4)).map(x=>routeLink('learn/'+x.id,esc(x.title.split('：')[0]),'btn small')).join('')}</div></div>`;
 return body+`<div class="content-with-toc learning-page"><div>${main}</div>${toc(q.sections.map((s,i)=>['learn-'+q.id+'-'+i,String(i+1).padStart(2,'0'),s.title]))}</div>`+footer();
}
function updateAscendancyProgress(){const el=$('#ascendancy-next');if(!el)return;
 const n=Number(getStore('earned-ascendancy','0'));
 const item=D.chineseAscendancy.steps.find(x=>x.from===n);
 el.innerHTML=item?`<strong>现在看：${esc(item.title)}</strong><br>${esc(item.ticket)}。完成并在祭坛领取后，从${n}点变为${n+2}点。`:'<strong>8点已齐，不需要再做拿点任务。</strong>之后按需要刷试炼奖励；不会获得第10点。';
 $$('[data-earned]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.earned)===n)));
 $$('[data-asc-card]').forEach(c=>c.classList.toggle('asc-current',Number(c.dataset.ascCard)===n));
}

function guideR39(){let content=heading('START HERE / 入门与成长','从当前阶段开始','基础概念只讲一次。后面按目标、配置和做法继续，不在多个页面重复找。');content+=`<div class="route-grid">${[
 ['01','第一次玩','先选自己所在进度；基础操作、城镇功能和资料使用接成一条路线。','learn/start','新手从这里衔接'],['02','刚进入异界','先看 Lazy Exile 开荒推进与主树图；人物仍按 Fubgun 配置。','atlas-starter','从第一张地图开始'],['03','开始固定刷图','按同一套 Fubgun 方案核对树、大师和开图材料。','atlas/'+state.variant,'查看刷图方案']
].map(([n,t,d,r,l])=>`<div class="route-card"><div class="num">${n} / ENTRY</div><h3>${t}</h3><p>${d}</p>${routeLink(r,l+' '+icon('arrow',14),'text-link')}</div>`).join('')}</div>`;
 content+=sec('guide-essentials','01','剧情到异界，中间不要漏这几步',`<div class="panel">${[['ascendancy','升华点怎么拿','入口、门票、2／4／6／8点与奖励祭坛'],['permanent','永久奖励与功能解锁','30项奖励位置、第3组保证门票与任务收尾'],['readiness','出发前一次验收','技能资源、工艺风险、试炼与地图准备']].map(([id,t,desc])=>`<div class="source-row"><div><strong>${t}</strong><p class="small muted">${desc}</p></div>${routeLink('learn/'+id,'直接查看 '+icon('arrow',12),'text-link')}</div>`).join('')}</div>`);
 content+=sec('guide-path','02','人物成长路线',D.branches.slice(0,5).map((b,i)=>`<div class="timeline-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(b.profile.title)}</h3><p>${esc(b.profile.overview)}</p></div><div class="actions">${routeLink('gear','装备目标','btn small',{stage:'e0'+b.number})}${routeLink('character','人物技能','btn small',{stage:'e0'+b.number})}</div></div>`).join(''));
 content+=sec('guide-new-path','03','照着做之前，先补操作链',`<div class="context-tools">${routeLink('learn/build-use','构筑怎样实际装配','btn')}${routeLink('learn/acquisition','如何找装备与材料','btn')}${routeLink('learn/map-run','一张地图完整循环','btn')}${routeLink('learn/audit-beginner','本轮审核与未完成项','btn')}</div>`);content+=expand('剧情过渡与原有练级资料',`<p>保留原来的 1–60＋剧情资料，不把 Early 异界阶段当作人物 1 级教学。六个剧情阶段的详稿与完整工具从下方直接进入，保留原有内容和操作。</p>${Array.from({length:6},(_,i)=>archive('l0'+(i+1)+'.html','剧情阶段 '+(i+1))).join('　')}`);return content+footer()}
function basics(){return note('新手完整入口：'+routeLink('learn/start','从当前进度开始')+'。下面只解释装备术语，不把术语页当全流程。')+heading('FOUNDATIONS / 只在这里讲基础','先分清这几件事','之后的装备与异界页面，直接进入实际做法。')+D.fundamentals.map(([n,t],i)=>sec('base-'+i,String(i+1).padStart(2,'0'),esc(n),`<div class="panel panel-inner"><p>${esc(t)}</p></div>`,'',i===0)).join('')+footer()}

let starterView='start';
function starterImage(){const a=D.atlasStarter;return a.images.find(x=>x.id===starterView)||a.images[0]}
function starterImagePanel(){const g=starterImage();return `<div class="starter-figure-head"><div><strong>${esc(g.stage)}</strong><p class="small muted">${esc(g.description)}</p></div>${safeLink(g.url,'打开原图')}</div><div class="starter-figure-body"><div id="starter-image-status" class="starter-image-status" role="status"><strong>Lazy Exile 原始加点图</strong><span>原图已逐张核对；此包未保存图片副本，需联网查看。</span><button class="btn primary" data-starter-load>联网显示原图</button></div><img id="starter-tree-image" alt="Lazy Exile ${esc(g.title)}，原作者异界主树截图" hidden data-starter-expand tabindex="0" role="button" aria-label="放大 Lazy Exile 加点原图"></div><div class="image-bottom"><span>不会自动联网；点击按钮后从 Mobalytics 加载。</span><button class="btn small" data-starter-expand>大图查看</button></div>`}
function atlasStarterBase(){const a=D.atlasStarter;let content=heading('ATLAS / 新手开荒','从第一张异界地图开始','先把开荒推进走清楚，再选择专门刷什么。不更换你的 Fubgun 冰射人物。',false,routeLink('atlas-choose','查看七套成型方案 '+icon('arrow',12),'btn'));
 content+=`<div class="starter-credit"><span class="tag">开荒补充 · ${esc(a.author)}</span><span>原文更新 ${a.updated}</span>${safeLink(a.source,'作者完整攻略')}<span>人物 / 成型刷法：Fubgun</span></div>`;
 let main=sec('starter-route','01','先照这个顺序推进',`<div class="panel starter-brief"><b>开图准备</b><p>${esc(a.preparation)}</p></div><div class="panel"><table class="starter-route-table"><thead><tr><th>目标</th><th>推进顺序</th><th>完成要点</th></tr></thead><tbody>${a.route.map(row=>`<tr><td><span class="stepnum">${row[0]}</span><strong>${esc(row[1])}</strong></td><td>${esc(row[2])}</td><td>${esc(row[3])}</td></tr>`).join('')}</tbody></table></div><p class="caption">以上是 Lazy Exile 的主线速推思路，不是游戏规定每个人必须照同一顺序游玩。完整细节见原文。</p>`,'',true);
 main+=sec('starter-tree','02','主树加点：先看起步图',`<p class="starter-intro">${esc(a.tree_text)}</p><div class="starter-image-tabs" aria-label="Lazy Exile 分阶段原图">${a.images.map(g=>`<button class="btn" data-starter-view="${g.id}" aria-pressed="${g.id===starterView}">${esc(g.title)}</button>`).join('')}</div><div class="panel starter-figure" id="starter-figure">${starterImagePanel()}</div><p class="caption">三张图都可查看，不按人物等级隐藏。阶段按钮只切换这一位作者的开荒原图，不修改人物阶段或 Fubgun 刷取方案。</p>`);
 main+=sec('starter-rules','03','不要混淆的规则',`<div class="panel">${a.rules.map(x=>`<div class="starter-rule"><strong>${esc(x.title)}</strong><div><p>${esc(x.text)}</p>${safeLink(x.url,'GGG 规则出处')}</div></div>`).join('')}</div>`,'<p>官方规则校注 · 与作者路线分开</p>');
 main+=sec('starter-next','04','什么时候转到 Fubgun 刷法？',`<div class="panel starter-next"><p><span class="tag gray">本站衔接建议</span></p><p><strong>需要什么解锁、能打什么难度、材料够不够，三项对应上再采用。</strong></p><p class="small muted">先保留人物原配置。选定某套刷法后，对照它自己的主树多选项、玩法树、大师与碑牌，不能把开荒图当成七套通用配方。没有统一人物等级或伤害数字可保证完成。</p><div class="context-tools">${routeLink('atlas-choose','七套方案怎么选 '+icon('arrow',12),'btn primary')}${routeLink('gear','检查全身装备','btn',{stage:state.stage})}${routeLink('character','检查技能与资源','btn',{stage:state.stage})}</div></div>`);
 main+=expand('来源、原图与版本范围',`<p>${esc(a.boundary)}</p><p>只保留作者方向，没有复制整篇文章；中文地名为阅读说明，英文任务名用于对照。作者后期图的特定节点评价没有写成当前版本的永久禁点。</p><p>${safeLink(a.source,'Lazy Exile 完整文章')}　${routeLink('atlas-unlock','原有解锁资料（历史来源）','text-link')}</p><p class="small muted">${esc(a.download_attempt)}</p>`);
 return content+`<div class="content-with-toc starter-content"><div>${main}</div>${toc([['starter-route','01','开荒推进'],['starter-tree','02','分阶段加点图'],['starter-rules','03','规则与区别'],['starter-next','04','衔接成型刷法']])}</div>`+footer()}
function loadStarterImage(){const g=starterImage(),im=$('#starter-tree-image'),status=$('#starter-image-status');if(!im||!status)return;status.innerHTML='<span>正在请求作者原图…</span>';im.onload=()=>{if(im.isConnected){im.hidden=false;status.hidden=true;}};im.onerror=()=>{if(im.isConnected){im.hidden=true;status.hidden=false;status.innerHTML='<strong>原图未能加载</strong><span>当前浏览器网络可能无法访问图片源；文字攻略仍可离线阅读。</span>'+safeLink(g.url,'直接打开原图')+'<button class="btn" data-starter-load>重试加载</button>';}};im.src=g.url;}
function showStarterImage(){const g=starterImage();$('#image-title').textContent='Lazy Exile · '+g.title+' · 联网原图';const im=$('#modal-image');im.onload=null;im.onerror=()=>{$('#image-title').innerHTML='联网原图未能加载 · '+safeLink(g.url,'直接打开原图');};im.src=g.url;im.alt='Lazy Exile '+g.title+'；不是 Fubgun 方案图';im.style.width='100%';$('#image-dialog').showModal();}

function atlasUnlock(){let content=heading('ATLAS / 解锁与推进','进入异界，先做什么','推进解锁与长期刷奖励分开。人物升级的技能点，不在这里分配。');content+=note('新手按步骤阅读请看 '+routeLink('atlas-starter','新手异界开荒 · Lazy Exile')+'；以下保留原有解锁资料。');content+=`<div class="panel panel-inner">${D.atlasUnlock.map((x,i)=>`<div class="timeline-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div><span class="tag gray">沿用 R28 解锁说明</span></div>`).join('')}</div>`;content+=sec('unlock-next','02','接着研究哪套刷法？',routeLink('atlas-choose','先按条件选方案 '+icon('arrow',12),'btn')+atlasChoiceTable());content+=expand('版本细则和完整解锁资料',`<p>本版沿用已标明来源的任务细则，没有新增规则核验。0.5.5 要塞规则、其他玩法入口和原有说明保留在 R28。</p>${archive('atlas-unlock.html','解锁流程完整说明')}`);return content+footer()}
function toolIndex(){return heading('REFERENCE / 资料与工具','需要时，再来查','常用做法已经放回对应装备和方案页。这里保留查询、原件和完整工具。')+`<div class="tool-grid">${D.tools.map(t=>`<div class="tool-card"><span class="tag gray">${esc(t.group)}</span><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p>${t.route?routeLink('tools/'+t.route,'进入 '+icon('arrow',13),'text-link'):archive(t.file,'进入完整工具')}</div>`).join('')}</div>`+sec('all-documents','01','全部详稿与工具',documentCatalog())+sec('local-backup','02','本地准备记录',backupPanel())+footer()}
function dictRows(q=''){const entries=[...Object.entries(D.materials).map(([id,m])=>({id,name:m.zh,en:m.en,text:m.effect,note:m.check,url:m.url})),...D.augments.map(m=>({id:m.id,name:m.name,en:m.en,text:Object.entries(m.effects||{}).map(([s,v])=>(D.slots.find(x=>x.id===s)?.name||s)+'：'+v).slice(0,2).join('；'),note:m.note,url:m.url}))];let list=entries.filter(e=>(e.name+' '+e.en+' '+e.text).toLowerCase().includes(q.toLowerCase()));return list.map(e=>`<div class="dictionary-row"><div><strong>${esc(e.name)}</strong><div class="sub">${esc(e.en)}</div>${e.url?safeLink(e.url,'原有出处'):''}</div><div><p>${esc(e.text)}</p><div class="risk-inline">${esc(e.note)}</div></div></div>`).join('')||'<div class="empty-state">没有匹配的材料。</div>'}
function tools(kind,params){if(!kind)return toolIndex();if(kind==='dictionary')return heading('REFERENCE / 材料查询','材料与作用','沿用 R28 已收录条目；按名称和作用筛选。')+`<input class="library-search" id="dictionary-query" aria-label="搜索材料" placeholder="例如：磨刀石、钢铁、崇高、死灵…" value="${esc(params.get('q')||'')}"><div class="panel" id="dictionary-results">${dictRows(params.get('q')||'')}</div>`+footer();
if(kind==='filters')return filterDownloadPage();
if(kind==='builds')return heading('DOWNLOADS / 人物原件','六份人物构筑','原始文件保持不变，未因布局改版改动人物加点。')+`<div class="panel">${D.branches.map(b=>`<div class="source-row"><div><strong>${esc(b.label)}</strong><div class="sub">${esc(b.sourceFile)}</div></div>${b.downloadData?`<a class="btn" href="${b.downloadData}" download="${esc(b.download.split('/').pop())}">${b.ascendancyConflict?'只读文件':'下载原件'}</a>`:'<span class="tag gold">冲突原件保留于完整包</span>'}</div>`).join('')}</div>`+footer();
if(kind==='sources')return note('<strong>R39 人物天赋珠宝：</strong>'+routeLink('jewels','清单、原件节点与来源','text-link',{stage:state.stage})+'；作者建议与实际插装分开。')+note('<strong>R37 本轮审核：</strong>'+routeLink('learn/audit-beginner','新手可执行性与未完成项')+'。')+note('<strong>R33 历史内容审核：</strong>'+routeLink('learn/audit','40项覆盖与版本纠错')+'。升华与试炼规则为独立研究补充，不冒充Fubgun专属加点。')+note('<strong>R32 新增独立开荒补充：</strong>'+routeLink('atlas-starter','Lazy Exile 新手异界开荒')+'。Fubgun 人物与七套刷法保留；下方七套核对是 R31 的已记录结果。')+heading('SOURCES / 来源与范围','保留依据，也保留缺项','R31对七条作者页面逐条复核；正文、图下说明、大师图示与旧快照分开。')+note('<strong>R31历史核对：</strong>当时已读取七套原页，在R30配套记录上补入两处图下要求及各套大师名称。R33另加官方规则校注，不重新导出互动节点。主体与原图保留；读取可见正文不代表取得动态节点导出。')+sec('limits','01','未补造的内容',`<div class="panel panel-inner"><p class="small">七套记录已经收录。仍待明确的是：作者未写的具体地图门槛或完整操作、Lineage Gems首轮碑牌数量关系、未展开动态节点与尚未核验的大师效果、完整人物连线与合法逐点次序，以及客户端和实战验证。</p><p class="small muted">查看${routeLink('atlas-choose','七套条件对照')}可定位各套原文范围。历史R28详稿保留原文，七套原文和R33当前规则校注分开显示，使用前一并核对。</p></div>`)+sec('sources','02','已有出处',`<div class="panel">${D.sources.map(s=>`<div class="source-row"><div><strong>${esc(s.title)}</strong>${s.note?`<div class="sub">${esc(s.note)}</div>`:''}</div>${safeLink(s.url,'来源')}</div>`).join('')}</div>`)+footer();
if(kind==='metrics')return heading('REFERENCE / 数值依据','底材与成品参考','按当前阶段显示原有核算。基础数值、词缀后数值和品质分开。',true)+`<div class="panel">${phase().items.filter(i=>!i.utility).map(i=>`<div class="dictionary-row"><div><strong>${esc(i.title)} · ${esc(i.name)}</strong><div class="sub">${esc(i.craftShort)}</div></div><div>${esc(i.goal)}<div class="sub">${esc(i.example)}</div>${routeLink('item/'+i.uid,'查看这件装备 →','text-link',{stage:state.stage})}</div></div>`).join('')}</div>`+footer();return toolIndex()}

function documentCatalog(){return `<input class="library-search" id="document-query" aria-label="筛选全部详稿" placeholder="按标题或分区筛选，例如：剧情、强化、过滤器"><div id="document-results">${documentRows('')}</div>`}
function documentRows(q){const groups=['入门与成长路线','人物与技能','装备养成','异界与刷图','资料与工具'];q=q.toLowerCase();return groups.map(g=>{const rows=D.documents.filter(d=>d.group===g&&(d.title+' '+d.file+' '+g+' '+(d.keywords||'')).toLowerCase().includes(q));return rows.length?expand(g+' · '+rows.length+' 篇',`<div class="doc-grid">${rows.map(d=>`<div>${archive(d.file,esc(d.title))}<div class="sub">${esc(d.file)}</div></div>`).join('')}</div>`,!!q):''}).join('')||'<div class="empty-state">没有匹配的详稿。</div>'}
function backupPanel(){return `<div class="panel panel-inner"><p class="small muted">导出主站可访问的阶段、方案和勾选记录。专用工具若单独存储，请使用该工具里的导出按钮另行备份；不是读取游戏角色。</p><div class="context-tools"><button class="btn" data-export-settings>导出记录 JSON</button><label class="btn" for="settings-file">导入记录 JSON</label><input id="settings-file" type="file" accept="application/json,.json" hidden></div><p class="sub">导入仅合并文件包含的本站记录；未包含的项目保持原状，不能跨浏览器自动同步。</p></div>`}
function referencePage(params){const fd=params.get('doc');if(fd==='filters.html')return filterDownloadPage();if(fd==='filter-legend.html')return filterGuidePage(params);const file=params.get('doc')||'beginner-guide.html';const d=D.documents.find(x=>x.file===file);if(!d)return heading('REFERENCE / 资料','未找到该资料')+note('请从资料目录选择有效条目。',true)+routeLink('tools','返回资料与工具','btn');
 if(!PACKAGED)return heading('REFERENCE / 完整工具',esc(d.title))+note('单文件版提供核心阅读。使用本条详稿及原有专用工具，请解压完整整合包并打开 index.html。')+routeLink('tools','返回资料目录','btn')+footer();
 const query=params.get('query')||'',anchor=params.get('anchor')||'';const suffix=(query?'?'+query:'')+(anchor?'#'+anchor:'');
 const atlasOld=/^(atlas-|fubgun-|beginner-guide)/.test(file);const refresh=atlasOld?note('<strong>这是R28历史详稿。</strong>旧页中“六套正文尚未取得”的状态已被R30更新；七套地图、碑牌、大师与操作请看 '+routeLink('atlas-choose','R31原页核对配套')+'。历史内容原样保留，不代表当前方案。',true):'';
 return heading('REFERENCE / '+esc(d.group),esc(d.title),'原有详稿与工具在同一框架内使用；数据与工艺内容沿用 R28。',false,routeLink('tools','资料目录','btn'))+refresh+`<div class="reference-action"><span class="small muted">${esc(file)}</span><a class="text-link" href="R28原站/${esc(file+suffix)}" target="_blank" rel="noopener">单独打开原版 ↗</a></div><div class="reference-frame"><iframe id="reference-frame" src="pages/reference/${esc(file+suffix)}" title="${esc(d.title)}" data-document="${esc(file)}" style="height:900px" loading="eager"></iframe></div>`+footer();}
function acceptLocalKey(k){return /^(fubgun-|poe2-c-)/.test(k)}
function exportSettings(){const data={schema:'fubgun-local-settings-v1',version:'R37.1',created:new Date().toISOString(),entries:{}};try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(acceptLocalKey(k))data.entries[k]=localStorage.getItem(k)}}catch{toast('当前浏览器不允许读取本地记录。');return}const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Fubgun_本地准备记录_R37_1.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已导出本浏览器的准备记录。')}
async function importSettings(file){if(!file)return;try{if(file.size>5*1024*1024)throw new Error('文件超过5MB，请使用本站导出的记录文件');const d=JSON.parse(await file.text());if(d.schema!=='fubgun-local-settings-v1'||!d.entries||typeof d.entries!=='object'||Array.isArray(d.entries))throw new Error('不是有效的本站记录文件');const pairs=Object.entries(d.entries).filter(([k,v])=>acceptLocalKey(k)&&typeof v==='string');for(const[k,v]of pairs)localStorage.setItem(k,v);state.stage=getStore('stage','e01');if(!D.stages.some(s=>s.id===state.stage))state.stage='e01';state.variant=getStore('variant','expedition');if(!D.variants.some(s=>s.id===state.variant))state.variant='expedition';state.density=getStore('compact','no')==='yes';render();toast('已合并 '+pairs.length+' 项本地记录。')}catch(e){toast('导入失败：'+e.message)}}
window.addEventListener('message',e=>{const f=$('#reference-frame');if(!f||e.source!==f.contentWindow)return;const m=e.data||{};if(m.type==='fubgun-r29-height'&&m.doc===f.dataset.document&&Number.isFinite(m.height)){f.style.height=Math.max(500,Math.min(250000,m.height+8))+'px';}if(m.type==='fubgun-r29-doc'&&D.documents.some(d=>d.file===m.doc)){navigate('reference',{doc:m.doc,...(m.query?{query:m.query}:{}),...(m.anchor?{anchor:m.anchor}:{})})}});

// R37: generated from complete local filter rules. No network or game scanning.
let fgState={file:'01',mode:'Show',category:'all',q:'',bg:'all',page:0};
const FG_COLORS={Red:'红',Green:'绿',Blue:'蓝',Brown:'棕',White:'白',Yellow:'黄',Cyan:'青',Grey:'灰',Orange:'橙',Pink:'粉',Purple:'紫'};
const FG_COLOR_RGB={Red:'#ed4141',Green:'#56b46a',Blue:'#6594ed',Brown:'#a56d38',White:'#f4f4f4',Yellow:'#ead847',Cyan:'#49d6d6',Grey:'#b0b0b0',Orange:'#f29142',Pink:'#e86dbd',Purple:'#b680ed'};
const FG_SHAPES={Circle:'圆形',Diamond:'菱形',Hexagon:'六边形',Square:'方形',Star:'星形',Triangle:'三角形',Cross:'十字',Moon:'月牙',Raindrop:'水滴',Kite:'风筝',Pentagon:'五边形',UpsideDownHouse:'倒房屋形'};
const FG_FIELD={ItemLevel:'物品等级',AreaLevel:'掉落区域等级',GemLevel:'宝石本体等级',WaystoneTier:'寻路石阶级',Quality:'品质',Sockets:'孔数',Width:'背包宽度',Height:'背包高度',UnidentifiedItemTier:'未鉴定物品阶级',DropLevel:'开始掉落等级',StackSize:'堆叠数量',BaseEnergyShield:'基础能量护盾',BaseEvasion:'基础闪避',BaseArmour:'基础护甲',BaseType:'物品底材／名称',Class:'物品类别',Rarity:'稀有度',Corrupted:'腐化',Mirrored:'镜像',Identified:'已鉴定',TwiceCorrupted:'双重腐化',AnyEnchantment:'附魔',AlwaysShow:'强制显示标记',HasVaalUniqueMod:'瓦尔暗金词缀标记',IsVaalUnique:'瓦尔暗金',HasExplicitMod:'显性词缀匹配'};
const FG_BOOL=['Corrupted','Mirrored','Identified','TwiceCorrupted','AnyEnchantment','AlwaysShow','HasVaalUniqueMod','IsVaalUnique'];
const FG_NUM=['ItemLevel','AreaLevel','Quality','Sockets','Width','Height','UnidentifiedItemTier','GemLevel','WaystoneTier','DropLevel','StackSize','BaseEnergyShield','BaseEvasion','BaseArmour'];
function fgData(){return D.filterGuide}
function fgColorValue(a,k){if(!a)return null;let t=a.map(Number);return [...t.slice(0,3),t.length>3?t[3]:(k==='SetBackgroundColor'?240:255)]}
function fgCss(a,k){const t=fgColorValue(a,k);return t?`rgba(${t.slice(0,3).join(',')},${t[3]/255})`:null}
function fgColorName(a){if(!a)return '未指定';let [r,g,b]=a.map(Number);if(a.length>3&&+a[3]===0)return '透明';const exact={'0,0,0':'黑','20,20,0':'近黑','60,0,0':'暗红','65,0,0':'暗红','70,0,20':'暗红','0,75,30':'深绿','0,50,0':'深绿','10,60,40':'墨绿','30,0,70':'深紫','47,0,74':'深紫','50,0,75':'深紫','0,16,198':'亮蓝','0,255,195':'青绿','0,255,251':'亮青','245,105,90':'珊瑚红','245,139,87':'橙','240,180,100':'浅橙','220,0,255':'亮紫','180,75,225':'紫','255,0,255':'洋红','75,75,0':'暗黄','235,220,245':'浅紫','6,0,60':'深蓝紫','35,35,35':'深灰','255,6,6':'亮红'};if(exact[[r,g,b]])return exact[[r,g,b]];if(Math.max(r,g,b)-Math.min(r,g,b)<22)return r>230?'白':r>150?'浅灰':r>60?'灰':'近黑';if(r>190&&g>160&&b<150)return '黄／橙';if(r>150&&g>130&&b>130)return '浅色';if(r>=g&&r>=b)return b>g*1.25?'粉／紫':'红／棕';if(g>=r&&g>=b)return b>g*.65?'青绿':'绿';return r>b*.5?'紫':'蓝'}
function fgColorDetail(a,k){if(!a)return '未指定：继承前置规则或客户端默认';let t=fgColorValue(a,k);return `${fgColorName(t)} · RGB ${t.slice(0,3).join('/')} · 透明度 ${t[3]}/255`}
function fgValue(k,v){const names=fgData().names,classes=fgData().classNames;return v.map(x=>({'Normal':'普通白装','Magic':'魔法蓝装','Rare':'稀有黄装','Unique':'暗金','True':'是','False':'否','==':'精确为','=':'等于','>=':'≥','<=':'≤','!=':'不等于','!':'不等于'}[x]||names[x]||classes[x]||x)).join('、').replace(/、([≥≤<>])、/g,' $1 ').replace(/^(≥|≤|>|<)、/,'$1 ')}
function fgCondition(k,v,limit=false){let text=fgValue(k,v);if(limit&&text.length>160)text=text.slice(0,160)+'…（展开完整规则查看）';return `<div class="fg-condition"><b>${esc(FG_FIELD[k]||k)}</b><span>${esc(text)}</span></div>`}
function fgIcon(args){if(!args||args[0]==='-1')return '<span class="muted">未设图标</span>';let color=FG_COLOR_RGB[args[1]]||'#ddd',sh=args[2],shape={Circle:'<circle cx="12" cy="12" r="8"/>',Diamond:'<path d="m12 2 10 10-10 10L2 12Z"/>',Square:'<rect x="4" y="4" width="16" height="16"/>',Triangle:'<path d="M12 2 23 21H1Z"/>',Hexagon:'<path d="m7 3 10 0 5 9-5 9H7l-5-9Z"/>',Star:'<path d="m12 1 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/>',Cross:'<path d="M9 2h6v7h7v6h-7v7H9v-7H2V9h7Z"/>',Pentagon:'<path d="m12 2 10 8-4 12H6L2 10Z"/>',Kite:'<path d="M12 1 22 9 12 23 2 9Z"/>',UpsideDownHouse:'<path d="M3 3H21V13L12 23 3 13Z"/>',Moon:'<path d="M16 2a10 10 0 1 0 6 15A10 10 0 0 1 16 2Z"/>',Raindrop:'<path d="M12 1C9 6 3 12 3 16a9 9 0 0 0 18 0c0-4-6-10-9-15Z"/>'}[sh]||'<circle cx="12" cy="12" r="7"/>';return `<span class="fg-map-icon"><svg width="${[22,18,14][+args[0]]||18}" height="${[22,18,14][+args[0]]||18}" viewBox="0 0 24 24" fill="${color}" aria-hidden="true">${shape}</svg>${esc((FG_COLORS[args[1]]||args[1])+'色'+(FG_SHAPES[sh]||sh))} · ${({'0':'大号','1':'中号','2':'小号'})[args[0]]||esc(args[0])}</span>`}
function fgSound(a){let s=a.CustomAlertSound||a.CustomAlertSoundOptional||a.PlayAlertSound||a.PlayAlertSoundPositional;if(!s)return '本条未设置额外提示音';if(s[0]==='None')return '明确关闭额外提示音';if(a.CustomAlertSound||a.CustomAlertSoundOptional)return '自定义文件 '+s.join(' ');return `${s[0]}号 · 音量${s[1]||50}${a.PlayAlertSoundPositional?' · 定位声音':''}`}
function fgEffect(a){let p=a.PlayEffect;return p&&p[0]!=='None'?`${FG_COLORS[p[0]]||p[0]}色光柱 · ${p[1]==='Temp'?'落下时短暂显示':'持续显示'}`:p?'明确关闭光柱':'本条未设置光柱'}
function fgSwatch(a,label,mode='Show'){let style=`color:${fgCss(a.SetTextColor,'SetTextColor')||'#d5d9de'};background:${fgCss(a.SetBackgroundColor,'SetBackgroundColor')||'repeating-linear-gradient(45deg,#20262b 0 8px,#293137 8px 16px)'};border:2px ${a.SetBorderColor?'solid':'dashed'} ${fgCss(a.SetBorderColor,'SetBorderColor')||'#78838a'};font-size:${Math.max(13,Math.min(24,(+(a.SetFontSize?.[0]||32))*.52))}px;`;return `<div class="fg-swatch-stage"><span class="fg-swatch" style="${style}">${esc(label)}</span>${mode==='Hide'?'<span class="fg-hidden-label">隐藏规则的样式，不代表平时可见</span>':''}</div>`}
function fgFields(a){return `<dl class="fg-fields"><div><dt>文字</dt><dd>${esc(fgColorDetail(a.SetTextColor,'SetTextColor'))}</dd></div><div><dt>底色</dt><dd>${esc(fgColorDetail(a.SetBackgroundColor,'SetBackgroundColor'))}</dd></div><div><dt>边框</dt><dd>${esc(fgColorDetail(a.SetBorderColor,'SetBorderColor'))}</dd></div><div><dt>字号</dt><dd>${esc(a.SetFontSize?.[0]||'本条未设')}</dd></div><div><dt>声音</dt><dd>${esc(fgSound(a))}</dd></div><div><dt>光柱</dt><dd>${esc(fgEffect(a))}</dd></div><div><dt>小地图</dt><dd>${fgIcon(a.MinimapIcon)}</dd></div><div><dt>落地音</dt><dd>${(a.DisableDropSound&&a.DisableDropSound[0]!=='False')?'关闭物品自身落地音':a.EnableDropSound?'开启物品自身落地音':'本条未改变落地音'}${a.DisableDropSoundIfAlertSound?'；有警报时关闭落地音':''}</dd></div></dl>`}
function fgFileLink(k,label='下载'){let f=fgData().files[k];return `<a class="btn small" href="${PACKAGED?esc(f.url):f.data}" download="${esc(f.name)}">${label}</a>`}
function filterDownloadPage(){return heading('FILTERS / 过滤器','按阶段选择，不按编号升级','02剧情 → 01异界起步；准备减少拾取再选03，04不作为新手默认。')+`<div class="panel fg-downloads"><div class="fg-download-row"><span class="fg-step">02</span><div><h3>剧情：用02原版</h3><p>保留弓系剧情提醒。此次未提供新的02，不标成“当前作者版已复核”。</p></div>${fgFileLink('02','下载02')}</div><div class="fg-download-row"><span class="fg-step">01</span><div><h3>异界起步：01原版，或01补充版（金币已修正）</h3><p>01本来就显示基础材料、升级宝石和普通试炼门票。自己做装备、要留海盗外套等白／蓝底材和基础碎片，就选补充版；仍属于01开荒档，不用先换03。</p><div class="fg-download-small">原01在异界只显示单堆至少5000的金币；本补充版已解除异界金币数量门槛。五种底材和四类碎片补充保留，其他规则与贵重提示不动。</div></div><div class="fg-download-actions">${fgFileLink('01b','下载01补充版 · 金币修正')}${fgFileLink('01','保留01原版')}</div></div><div class="fg-download-row"><span class="fg-step">03</span><div><h3>后期刷图：原03，或03补材料版</h3><p>想减少普通物品，用原03；还要自捡材料和门票，才选补材料版。注意：这两份03在异界仍隐藏金币，本次没有修改它们。补材料版就是之前称作“自用版”的文件，不是另一套人物BD。</p></div><div class="fg-download-actions">${fgFileLink('03','下载03原版')}${fgFileLink('03m','可选：03补材料')}</div></div><div class="fg-download-row"><span class="fg-step">04</span><div><h3>超严格：材料与装备充足后按需</h3><p>不按角色等级强制切换。会隐藏多种基础材料、普通试炼门票以及异界金币；先查所需物品再采用。</p></div>${fgFileLink('04','下载04')}</div></div>`+note('<strong>一次只启用一份，不叠加。</strong>01补底材与碎片、03补材料都是本站派生选项，不是Fubgun官方更新。原文件全部单独保留。')+sec('filter-review','01','01到底改了哪里',`<div class="panel panel-inner"><p><b>只补五种白／蓝底材：</b>海盗外套、飞矢箭袋、宏伟护腕、骑兵长靴、沙漠之帽；限定掉落区域≥65、未腐化、未镜像。原来已能显示的高优先级装备仍按原提示。</p><p><b>另补四种基础碎片：</b>蜕变碎片、富豪碎片、巧匠碎片、炼金碎片。区域65及以上，单个也显示；采用淡棕字、深棕底、短暂白光柱和小灰圆图标，不额外播放大货警报。机会碎片、裂隙／拟像等裂片已有显示，保留原提示。</p><p class="muted">不补全所有白／蓝装备，不抬高普通材料警报；不是每件显示的装备都值得加工。四种基础碎片补充保留。R37.1只新增区域65及以上金币显示，不设金币数量门槛；5000及以上的大堆仍用原高亮。小堆沿用原灰字、黑边和近黑底，不另加警报。剧情金币和智慧卷轴保持原规则。</p><div class="actions">${routeLink('filter-guide','颜色、底色、声音完整图例','btn',{f:'01'})}${routeLink('filter-check','查某件物品会不会隐藏','btn',{f:'01'})}${routeLink('filter-guide','查看新增底材与碎片提示','text-link',{f:'01b',q:'R37_01_',mode:'all'})}</div></div>`)+note('<strong>金币修正只应用于01补充版。</strong>原01／R37旧补充版在异界隐藏单堆不足5000的金币；原03、03补材料及04在异界隐藏金币。本次不改变这些原文件。'+routeLink('filter-check','对照金币1000的实际规则 →','text-link',{f:'01b',sample:'gold_79_1000'}))+sec('filter-shards','02','整颗通货显示，不代表碎片也显示',fgShardPairs())+expand('安装与来源核对',`<p>将所选.filter放入你当前游戏使用的过滤器目录，在游戏设置的过滤器下拉菜单中选择该文件。不要保留.txt后缀；原作者01/02/03/04无需覆盖。</p><p>本页按用户提供的文件核对。01/03/04已与R36原件逐字节对比；02沿用原快照。文件内NeverSink与FilterBlade署名保留，R37曾只增底材和碎片两条显示块；R37.1在此基础上只新增一条异界金币显示，不改其他文件。</p><p>提示色不是价格保证；未作游戏客户端实测。上线包只提供网页与文件，不会替你更新游戏设置。</p>${PACKAGED?'<a href="data/R37-filter-catalog.json" download>下载完整规则数据</a>':''}`)+footer()}
function fgQuickPanel(k){
 const f=fgData().files[k];
 const common=[
  ['custom','黑底白边／暗红底：作者指定底材','按具体底材、稀有度、物品等级决定；不是所有同类装备，也不保证卖价。'],
  ['quality2armorany','亮蓝底：带品质防具回收候选','01这条看品质≥10、未鉴定物品阶级≤2等条件；不表示装备必定更强。'],
  ['j2a','暗黄底：有未鉴定阶级的黄装首饰','阶级条件与物品名单共同作用，不是地图T级；03/04可能关闭同一档。'],
  ['j2b','深紫底：带阶级的魔法首饰','深紫底也会用于其他类别，必须连同文字、边框和物品名称看。'],
  ['toplevelflasks','墨绿底：药剂候选','先看物品等级、品质和稀有度；边框可能区分高等级与普通候选。'],
  ['gear4a','深绿底＋青绿字：高阶级／特殊装备','未鉴定阶级、特殊状态或指定稀有底材都可能共用这组样式。'],
  ['c','橙底：某一档通货／材料','完整通货与碎片分开匹配；同类材料可能处于不同提示档。'],
  ['trialkeysanctum3','紫底：试炼门票','票的提示档位不等于能拿哪次升华点；仍看门票本身的试炼资格。'],
  ['otherskilleg','青字：未切割技能宝石','宝石级别和掉落区域会影响规则；18级掉在更高区域可能变成另一种提示。'],
  ['spirit20','白底红字：高优先级物品','不只对应某一种通货；20级精魂宝石等也会共用，不能单凭颜色报价格。'],
 ];
 let chosen=[];
 for(let [tier,title,note]of common){let r=f.rules.find(x=>x.action==='Show'&&!x.continue&&x.tier===tier&&(tier!=='j2b'||x.type.includes('magic'))&&(tier!=='c'||x.type==='currency'));if(r&&!chosen.some(x=>x.r.line===r.line))chosen.push({r,title,note});}
 return `<details class="expand fg-quick"><summary>常见提示先看这里｜再用下方完整查询找其他样式</summary><div class="fg-quick-grid">${chosen.map(({r,title,note})=>`<div class="fg-quick-item"><strong>${esc(title)}</strong>${fgSwatch(r.actions,r.examples[0]||r.category)}<p>${esc(note)}</p><a href="${path('filter-guide',{f:k,q:r.header,mode:'all'})}">查这条的完整条件 · L${r.line}</a></div>`).join('')}</div></details>`;
}

function fgShardPairs(){const pairs=[['蜕变石','蜕变碎片','Transmutation Shard'],['富豪石','富豪碎片','Regal Shard'],['巧匠石','巧匠碎片',"Artificer's Shard"],['炼金石','炼金碎片','Alchemy Shard']];return `<div class="table-scroll"><table class="fg-compare"><thead><tr><th>完整通货</th><th>对应碎片</th><th>原01（整颗 / 碎片）</th><th>01补充版（整颗 / 碎片）</th></tr></thead><tbody>${pairs.map(([whole,shard,en])=>{let sample=fgData().samples.find(x=>x.item.BaseType===en&&x.item.AreaLevel===79&&x.item.StackSize===1);return `<tr><td>${esc(whole)}</td><td>${routeLink('filter-check',esc(shard),'text-link',{f:'01b',sample:sample.id})}</td><td>显示 / <b>隐藏</b></td><td>显示 / <b>显示</b></td></tr>`}).join('')}</tbody></table></div><p class="small muted">上表按区域79、普通单个掉落核对；点击碎片可修改区域、数量等条件。新补充规则适用于区域65及以上。机会碎片及裂隙／拟像等裂片原有显示规则保留。</p>`}

function fgSelect(k){return `<label>正在看哪一份<select id="fg-file">${fgData().order.map(i=>`<option value="${i}" ${k===i?'selected':''}>${esc(fgData().files[i].title)}</option>`).join('')}</select></label>`}
function filterGuidePage(params){let k=params.get('f')||'01';if(!fgData().files[k])k='01';fgState={file:k,q:params.get('q')||'',category:'all',mode:params.get('mode')||'Show',bg:'all',page:0};const f=fgData().files[k],st=fgData().stats[k];return heading('FILTER LEGEND / 全量图例','颜色、底色与提示：按规则查','不是只用红、黄、蓝分档。先选择正在使用的过滤器，再按底色、物品或提示类型查询。')+`<div class="fg-top-links">${routeLink('tools/filters','← 过滤器选择与下载','text-link')}${routeLink('filter-check','查物品的最终提示 →','text-link',{f:k})}</div><div class="fg-status"><strong>${esc(f.title)}</strong><span>${st.blocks}条有效规则 · ${st.styles}组显式样式</span><span>${f.original?'原文保留':'本站补充版'}</span></div>`+note('这里展示<strong>单条规则明确设置的样式</strong>。未指定字段用虚线／棋盘格提示，不冒充游戏默认色；最终提示可能继承前面的装饰规则。<b>同底色可以代表多类物品，没有额外提示音也不等于没有落地声音。</b> 标签和图标为网页示意，具体像素外观以游戏为准。')+`${fgQuickPanel(k)}<div class="fg-controls">${fgSelect(k)}<label>规则类型<select id="fg-mode"><option value="Show" ${fgState.mode==='Show'?'selected':''}>显示规则</option><option value="all" ${fgState.mode==='all'?'selected':''}>全部有效规则</option><option value="Hide" ${fgState.mode==='Hide'?'selected':''}>隐藏规则</option><option value="Continue" ${fgState.mode==='Continue'?'selected':''}>装饰叠加规则</option></select></label><label>物品分类<select id="fg-category"><option value="all">所有分类</option>${[...new Set(f.rules.map(x=>x.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="fg-search-label">搜索<input id="fg-q" type="search" placeholder="蓝底、白边、巨灵币、磨刀石、底材、声音编号…" value="${esc(fgState.q)}"></label></div>`+`<details class="expand fg-palette-box"><summary>按底色找提示（每种实际底色均列出）</summary><div id="fg-palette" class="fg-palette">${fgPalette()}</div></details><div class="fg-resultbar"><span id="fg-count"></span><button class="btn quiet small" data-fg-clear>清除筛选</button></div><div id="fg-rules" class="fg-grid">${fgRuleResults()}</div><div id="fg-pagination" class="fg-pagination"></div>`+expand('先看懂声音、边框、光柱与装饰叠加',`<div class="fg-help-grid"><p><b>声音编号不是价值等级。</b>例如2号与6号是不同内置音效ID，后面的300是音量参数。这里不伪造试听，原文件未附带音频。</p><p><b>光柱与小地图图标独立。</b>红光柱可以搭配蓝色圆点，标签也可能是其他底色。Temp表示落下时短暂显示，不带Temp为持续光柱。</p><p><b>颜色字段分别看。</b>文字、边框、底色独立设置；背景的透明度未写时按语法默认240/255，文字和边框默认255/255。</p><p><b>继续匹配不代表结束。</b>带Continue的规则先叠加部分字段，再向下判断。后续设置同字段时会覆盖；未设置则保留之前结果。</p><p><b>注释不执行。</b>以#开头的规则不计入有效规则；原文完整保存在下载文件中，不把注释中的显示设定当作实际生效。</p><p><b>未鉴定阶级不是当前词缀T级。</b>本页按原UnidentifiedItemTier值解释，不把它当人物等级、地图T级或保证有用的词缀。</p></div><p>${safeLink(fgData().sourceUrl,'官方过滤器语法')} · 只用来解释规则，不用它判断市场价格。</p>`)+footer()}
function fgPalette(){let f=fgData().files[fgState.file];let colors=[...new Set(f.rules.map(r=>r.actions.SetBackgroundColor?.join(' ')||'unset'))];return `<button class="fg-color-chip ${fgState.bg==='all'?'selected':''}" data-fg-bg="all">所有底色</button>`+colors.map(v=>`<button class="fg-color-chip ${fgState.bg===v?'selected':''}" data-fg-bg="${esc(v)}"><i style="background:${v==='unset'?'repeating-linear-gradient(45deg,#444 0 4px,#777 4px 8px)':fgCss(v.split(' '),'SetBackgroundColor')}"></i>${esc(v==='unset'?'未指定':fgColorName(v.split(' '))+' '+v.split(' ').slice(0,3).join('/')+' · '+Math.round((fgColorValue(v.split(' '),'SetBackgroundColor')[3])/255*100)+'%')}</button>`).join('')}
function fgFiltered(){const s=fgState;return fgData().files[s.file].rules.filter(r=>{if(s.mode==='Continue'&&!r.continue)return false;if(s.mode==='Show'&&(r.action!=='Show'||r.continue))return false;if(s.mode==='Hide'&&r.action!=='Hide')return false;if(s.category!=='all'&&r.category!==s.category)return false;if(s.bg!=='all'&&(r.actions.SetBackgroundColor?.join(' ')||'unset')!==s.bg)return false;let a=r.actions;let text=r.search+' '+r.raw+' '+r.conditions.map(([k,v])=>fgValue(k,v)).join(' ')+' '+fgColorName(a.SetBackgroundColor)+'底 '+fgColorName(a.SetTextColor)+'字 '+fgColorName(a.SetBorderColor)+'边 '+fgSound(a)+' '+fgEffect(a);return !s.q||text.toLowerCase().includes(s.q.toLowerCase())})}
function fgRuleResults(){let list=fgFiltered(),n=24;let max=Math.max(0,Math.ceil(list.length/n)-1);fgState.page=Math.max(0,Math.min(fgState.page,max));let slice=list.slice(fgState.page*n,fgState.page*n+n);return slice.map(r=>`<article class="fg-card" id="rule-${r.id}"><div class="fg-card-head"><span class="tag ${r.action==='Hide'?'gray':''}">${r.continue?'装饰叠加':r.action==='Hide'?'隐藏':'显示'}</span><small>原文 L${r.line}–${r.end}</small></div><h3>${esc(r.title)}</h3>${fgSwatch(r.actions,r.examples[0]||r.category,r.action)}<p class="fg-card-note">${esc(r.note)}</p>${fgFields(r.actions)}${expand('什么条件才触发？查看完整规则',r.conditions.map(([k,v])=>fgCondition(k,v)).join('')+`<pre class="fg-raw">${esc(r.raw)}</pre>`)}<button class="btn quiet small" data-fg-rule="${r.id}">查看匹配本条的预设样例</button></article>`).join('')||'<div class="empty-state">没有匹配规则。清除底色／分类，或改用英文原物品名检索。</div>'}
function fgRefresh(){if(!$('#fg-rules'))return;$('#fg-rules').innerHTML=fgRuleResults();$('#fg-palette').innerHTML=fgPalette();fgUpdateCount()}
function fgUpdateCount(){if(!$('#fg-count'))return;let n=fgFiltered().length,p=fgState.page,max=Math.max(1,Math.ceil(n/24));$('#fg-count').textContent=`找到 ${n} 条 · 第 ${p+1}/${max} 页 · 已覆盖文件内全部有效规则，可切换隐藏与装饰`;$('#fg-pagination').innerHTML=`<button class="btn small" data-fg-page="-1" ${p===0?'disabled':''}>上一页</button><span>${p+1} / ${max}</span><button class="btn small" data-fg-page="1" ${p+1>=max?'disabled':''}>下一页</button>`}
function fgCompare(op,a,b){switch(op){case '=':case '==':return a===b;case '!':case '!=':return a!==b;case '<':return a<b;case '>':return a>b;case '<=':return a<=b;case '>=':return a>=b;default:throw Error('未知比较符：'+op)}}
function fgMatches(k,v,item){let args=v.slice(),op='=';if(['=','==','!=','!','<','>','<=','>='].includes(args[0]))op=args.shift();if(k==='HasExplicitMod'){let count=/^\d+$/.test(args[0])?+args.shift():1;let got=(item[k]||[]).filter(m=>args.some(a=>op==='=='?m===a:m.includes(a))).length;return fgCompare(op==='='?'>=':op,got,count)}if(FG_BOOL.includes(k))return fgCompare(op,item[k],args[0]==='True');if(FG_NUM.includes(k))return ['!','!='].includes(op)?args.every(a=>fgCompare(op,+item[k],+a)):args.some(a=>fgCompare(op,+item[k],+a));if(k==='Rarity'){let rank={Normal:0,Magic:1,Rare:2,Unique:3};return ['!','!='].includes(op)?args.every(a=>fgCompare(op,rank[item[k]],rank[a])):args.some(a=>fgCompare(op,rank[item[k]],rank[a]))}if(op==='=='||op==='=')return args.some(a=>op==='=='?item[k]===a:String(item[k]).includes(a));if(op==='!='||op==='!')return args.every(a=>item[k]!==a);throw Error('未支持的条件：'+k)}
function fgEvaluate(rules,item){let actions={},origins={},trace=[],result='Show';for(let r of rules){if(r.conditions.every(([k,v])=>fgMatches(k,v,item))){result=r.action;for(let [k,v]of r.display){actions[k]=v;origins[k]=r.line}trace.push(r);if(!r.continue)break}}return {result,actions,origins,trace}}
function filterCheckPage(params){let k=params.get('f')||'01';if(!fgData().files[k])k='01';let id=params.get('sample')||'s0',sample=fgData().samples.find(s=>s.id===id)||fgData().samples[0];return heading('FILTER CHECK / 查物品','这件物品为什么显示，为什么隐藏？','选择样例或修改条件，按文件真实顺序计算最终设置；不读取游戏角色或背包。')+`<div class="fg-top-links">${routeLink('tools/filters','← 选择与下载','text-link')}${routeLink('filter-guide','完整颜色图例 →','text-link',{f:k})}</div><div class="panel panel-inner fg-check-panel"><div class="fg-controls">${fgSelect(k)}<label class="fg-sample-label">物品样例<select id="fg-sample">${fgData().samples.map(s=>`<option value="${s.id}" ${s.id===sample.id?'selected':''}>${esc(s.label)}</option>`).join('')}</select></label></div><div id="fg-form">${fgForm(sample.item)}</div><button class="btn fg-run" id="fg-run">计算当前条件</button><p class="small muted">显示的是规则判断，不保证这种属性组合会自然掉落，也不判断底材是否值得投资。特殊词缀、附魔、孔数等会改变命中结果。</p></div><div id="fg-output"></div>`+footer()}
function fgForm(it){return `<div class="fg-input-grid"><label>物品英文原名<input id="fg-base" value="${esc(it.BaseType)}"></label><label>物品类别<select id="fg-class">${[...new Set([...Object.keys(fgData().classNames),it.Class])].map(c=>`<option value="${esc(c)}" ${c===it.Class?'selected':''}>${esc(fgData().classNames[c]||c)}</option>`).join('')}</select></label><label>稀有度<select id="fg-rarity">${['Normal','Magic','Rare','Unique'].map((r,i)=>`<option value="${r}" ${r===it.Rarity?'selected':''}>${['白装','蓝装','黄装','暗金'][i]}</option>`).join('')}</select></label>${['AreaLevel','ItemLevel','GemLevel','WaystoneTier','Quality','Sockets','UnidentifiedItemTier','StackSize'].map(k=>`<label>${FG_FIELD[k]}<input id="fg-n-${k}" type="number" min="0" max="99999" value="${it[k]}"></label>`).join('')}</div>${expand('其他参与匹配的条件（默认来自所选样例）',`<div class="fg-input-grid">${['Width','Height','DropLevel','BaseEnergyShield','BaseEvasion','BaseArmour'].map(k=>`<label>${FG_FIELD[k]}<input id="fg-n-${k}" type="number" min="0" value="${it[k]}"></label>`).join('')}${FG_BOOL.map(k=>`<label class="fg-checkbox"><input id="fg-b-${k}" type="checkbox" ${it[k]?'checked':''}>${FG_FIELD[k]||k}</label>`).join('')}<label class="fg-mods">显性词缀名（英文原名，一行一个）<textarea id="fg-mods">${esc((it.HasExplicitMod||[]).join('\n'))}</textarea></label></div>`)}<p class="small muted">中文名称用于阅读，内部匹配仍按原文件英文名称。复制游戏里的中文名不等于自动完成客户端物品解析。</p>`}
function fgFormItem(){let it={BaseType:$('#fg-base').value.trim(),Class:$('#fg-class').value,Rarity:$('#fg-rarity').value,HasExplicitMod:$('#fg-mods').value.split('\n').map(s=>s.trim()).filter(Boolean)};for(let k of FG_NUM){it[k]=+$('#fg-n-'+k).value;if(!Number.isFinite(it[k])||it[k]<0)throw Error((FG_FIELD[k]||k)+'需要非负数字')}for(let k of FG_BOOL)it[k]=$('#fg-b-'+k).checked;return it}
function fgRun(){if(!$('#fg-output'))return;try{let k=$('#fg-file').value,it=fgFormItem(),f=fgData().files[k],r=fgEvaluate(f.rules,it),name=fgData().names[it.BaseType]||it.BaseType;$('#fg-output').innerHTML=`<section class="section first"><div class="section-title"><h2>${r.result==='Hide'?'此条件下：隐藏':'此条件下：显示'}</h2><span>${esc(f.title)}</span></div>${fgSwatch(r.actions,name,r.result)}<div class="panel panel-inner">${fgFields(r.actions)}<p class="small muted">上方为按样例累积的最终显式设置。仍未设置的字段继续由游戏默认提供，不用示意色充当客户端结果。</p></div></section><section class="section"><div class="section-title"><h2>同一件物品，换过滤器会怎样？</h2></div><div class="table-scroll"><table class="fg-compare"><thead><tr><th>过滤器</th><th>结果</th><th>最终命中行</th><th>提示音</th></tr></thead><tbody>${fgData().order.map(key=>{let v=fgEvaluate(fgData().files[key].rules,it);return `<tr><td>${esc(fgData().files[key].title)}</td><td><strong>${v.result==='Hide'?'隐藏':'显示'}</strong></td><td>${v.trace.at(-1)?.line||'默认'}</td><td>${esc(fgSound(v.actions))}</td></tr>`}).join('')}</tbody></table></div></section><section class="section"><div class="section-title"><h2>匹配顺序与字段来源</h2></div>${r.trace.map((x,i)=>`<details class="expand" ${i===r.trace.length-1?'open':''}><summary>${i+1}. L${x.line} · ${esc(x.title)} · ${x.continue?'继续向下匹配':'在此停止'}</summary><div class="expand-body">${x.conditions.map(([k,v])=>fgCondition(k,v)).join('')}<pre class="fg-raw">${esc(x.raw)}</pre></div></details>`).join('')||'<p>没有显式命中块，按默认显示；不是文件内一条新规则。</p>'}<div class="fg-origin">${Object.entries(r.origins).map(([key,line])=>`<span>${esc(({SetTextColor:'文字',SetBorderColor:'边框',SetBackgroundColor:'底色',SetFontSize:'字号',PlayAlertSound:'提示音',PlayEffect:'光柱',MinimapIcon:'小地图',DisableDropSound:'落地音'})[key]||key)} ← L${line}</span>`).join('')}</div></section>`}catch(e){$('#fg-output').innerHTML=note(esc(e.message),true)}}
function fgAfterRender(){fgUpdateCount();fgRun()}
document.addEventListener('input',e=>{if(e.target.id==='fg-q'){fgState.q=e.target.value.trim();fgState.page=0;fgRefresh()}});
document.addEventListener('change',e=>{let id=e.target.id;if(id==='fg-file'){navigate(current.section==='filter-check'?'filter-check':'filter-guide',{f:e.target.value,...($('#fg-sample')?{sample:$('#fg-sample').value}:{})});return}if(id==='fg-mode'||id==='fg-category'){fgState[id==='fg-mode'?'mode':'category']=e.target.value;fgState.page=0;fgRefresh();return}if(id==='fg-sample'){let s=fgData().samples.find(x=>x.id===e.target.value);$('#fg-form').innerHTML=fgForm(s.item);fgRun()}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-fg-bg]');if(b){fgState.bg=b.dataset.fgBg;fgState.page=0;fgRefresh();return}if(e.target.closest('[data-fg-clear]')){fgState.q='';fgState.category='all';fgState.bg='all';fgState.page=0;$('#fg-q').value='';$('#fg-category').value='all';fgRefresh();return}b=e.target.closest('[data-fg-page]');if(b){fgState.page+=+b.dataset.fgPage;fgRefresh();$('#fg-count').scrollIntoView({block:'start'});return}b=e.target.closest('[data-fg-rule]');if(b){let r=fgData().files[fgState.file].rules.find(x=>x.id===b.dataset.fgRule);let sample=fgData().samples.find(s=>r.conditions.every(([k,v])=>fgMatches(k,v,s.item)));if(sample)navigate('filter-check',{f:fgState.file,sample:sample.id});else toast('没有匹配本条的预设样例；可在查物品页按本条条件手动填写。');return}if(e.target.closest('#fg-run'))fgRun()});

let current={section:'gear',slot:null,params:new URLSearchParams()};
function parseHash(){let h=location.hash.replace(/^#\/?/,'')||'gear',i=h.indexOf('?');return {parts:(i>=0?h.slice(0,i):h).split('/'),params:new URLSearchParams(i>=0?h.slice(i+1):'')}}
function render(){const {parts,params}=parseHash();if(params.has('stage')&&D.stages.some(x=>x.id===params.get('stage'))){state.stage=params.get('stage');setStore('stage',state.stage)}let page=parts[0];current={section:page,slot:parts[1],params};let body='',group='gear',crumb='全身装备目标';
 try{if(page==='craft-timing'){body=craftTiming();group='gear';crumb='什么时候值得打造'}else if(page==='early-craft'){body=earlyCraft();group='gear';crumb='剧情／低投入工作台'}else if(page==='supplies'){body=supplies();group='gear';crumb='底材与材料循环'}else if(page==='troubleshoot'){body=troubleshoot();group='guide';crumb='卡关与故障排查'}else if(page==='coverage'){body=coverage();group='tools';crumb='覆盖审阅与待核实'}else if(page==='gear')body=gear();else if(page==='item'){body=itemPage(parts[1]||'bow',params);crumb=D.slots.find(x=>x.id===parts[1])?.name||'装备详情'}else if(page==='character'){body=character();group='character';crumb='人物配置与技能'}else if(page==='jewels'){body=jewelsPage();group='character';crumb='人物天赋珠宝清单'}else if(page==='special-jewels'){body=specialJewelsPage();group='character';crumb='特殊人物珠宝'}else if(page==='gems'){body=gemsPage();group='character';crumb='技能／辅助宝石清单'}else if(page==='special-gems'){body=specialGemsPage();group='character';crumb='血脉辅助（非人物天赋珠宝）'}else if(page==='atlas-starter'){body=atlasStarter();group='atlas';crumb='新手异界开荒'}else if(page==='atlas-choose'){body=atlasChoose();group='atlas';crumb='七套方案怎么选'}else if(page==='atlas'){body=atlasPage(parts[1]||state.variant);group='atlas';crumb=D.variants.find(x=>x.id===state.variant).zh}else if(page==='atlas-unlock'){body=atlasUnlock();group='atlas';crumb='解锁与推进'}else if(page==='guide'){body=parts[1]==='basics'?basics():guide();group='guide';crumb=parts[1]==='basics'?'基础概念':'入门与成长路线'}else if(page==='learn'){const q=D.learningPages[parts[1]]||D.learningPages.audit;body=learningPage(q.id);group=q.group;crumb=q.title;}else if(page==='reference'){body=referencePage(params);group='tools';crumb=D.documents.find(d=>d.file===params.get('doc'))?.title||'完整详稿';}else if(page==='filter-guide'){body=filterGuidePage(params);group='tools';crumb='过滤器完整图例'}else if(page==='filter-check'){body=filterCheckPage(params);group='tools';crumb='物品显示与隐藏判断'}else if(page==='tools'){body=tools(parts[1],params);group='tools';crumb=({dictionary:'材料查询',metrics:'数值依据',builds:'人物原件',filters:'过滤器',sources:'来源与缺项'})[parts[1]]||'资料与工具'}else {body=gear();current.section='gear';}
 $('#main-content').innerHTML=body;updateAscendancyProgress();fgAfterRender();
 const names={guide:'成长路线',character:'人物配置',gear:'装备与打造',atlas:'异界与产出',tools:'查询与下载'};
 $('#breadcrumb').innerHTML=`<span>${names[group]}</span><span class="crumb-sep">/</span><span>${esc(crumb)}</span>`;
 document.title=crumb+' · Fubgun 冰射攻略 · R40';nav(group);document.body.classList.toggle('compact',state.density);$('#density-toggle').textContent=state.density?'标准密度':'紧凑密度';
 $('#main-content').setAttribute('data-page',page);window.scrollTo(0,0);closeNav();r40AfterRender();
 }catch(e){console.error(e);$('#main-content').innerHTML=heading('DISPLAY / R37','页面暂时没有正确载入','没有修改原版资料。')+note(esc(e.message),true)+routeLink('gear','返回装备首页','btn');}
}
function navR39(group){const info=[['guide','book','入门与成长路线','guide'],['character','person','人物与技能','character'],['gear','gear','装备养成','gear'],['atlas','atlas','异界与刷图','atlas-starter'],['tools','tools','资料与工具','tools']];$('#main-nav').innerHTML=info.map(([id,ic,n,r])=>{let subs='';if(group===id){let links={guide:[['learn/start','新手从这里开始'],['guide','成长路线'],['guide/basics','基础概念'],['learn/permanent','永久奖励与功能'],['learn/readiness','出发前验收']],character:[['character','当前阶段配置'],['jewels','人物天赋珠宝'],['special-jewels','特殊人物珠宝'],['gems','技能／辅助宝石清单'],['special-gems','血脉辅助（非天赋珠宝）'],['learn/build-use','导入与装配检查'],['learn/ascendancy','升华点 · 0→8'],['learn/sekhemas','丝克玛试炼'],['learn/chaos','混沌试炼']],gear:[['gear','全身装备目标'],['item/bow','单件完整详情'],['learn/acquisition','装备与材料怎么找']],atlas:[['atlas-starter','新手开荒 · 先看这里'],['atlas-choose','七套方案怎么选'],['atlas/'+state.variant,'当前方案与配套'],['learn/activities','其他试炼与玩法']],tools:[['tools','全部资料'],['tools/filters','过滤器选择与下载'],['filter-guide','颜色、底色与声音'],['filter-check','查物品显示／隐藏'],['tools/dictionary','材料查询'],['learn/audit-beginner','新手复查与未完成项']]}[id];subs=`<div class="subnav">${links.map(([r,n],i)=>routeLink(r,n,(r===current.section||r===current.section+'/'+current.slot||(r==='item/bow'&&current.section==='item'))?'on':'',['character','jewels','special-jewels','gems','special-gems','gear','item/bow'].includes(r)?{stage:state.stage}:{})).join('')}</div>`}return routeLink(r,`${icon(ic,17)}<span>${n}</span>`,'nav-item '+(group===id?'active':''),['gear','character'].includes(r)?{stage:state.stage}:{})+subs}).join('')}
function closeNav(){$('#sidebar').classList.remove('open');$('#mobile-backdrop').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false')}
function navigate(r,params={}){location.hash=path(r,params)}
let toastTimer;function toast(t){const e=$('#toast');e.textContent=t;e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,3500)}
function imageView(view){state.view=view;const v=D.variants.find(x=>x.id===state.variant);$('#atlas-tree-image').src=v.views[view];$$('[data-image-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.imageView===view)))}
function showImage(id,original=false){$('#modal-image').onerror=null;$('#modal-image').onload=null;const v=D.variants.find(x=>x.id===id);if(!v)return;$('#image-title').textContent=v.name+' · '+(original?'完整原图':'当前视图');$('#modal-image').src=original?v.original:v.views[state.view];$('#modal-image').style.width='100%';$('#modal-image').alt='Fubgun '+v.name+' 用户提供的原始加点截图';$('#image-dialog').showModal()}
function searchData(q){let data=[...r40SearchEntries(),...j39SearchEntries(),...r38SearchEntries(),{title:'过滤器：选择、下载与01补底材碎片',text:'01/02/03/04 · 原版与补充版分清',route:'tools/filters',query:'过滤器 自用版 补材料 底材 碎片 富豪碎片 巧匠碎片 开荒 剧情'}, {title:'过滤器完整颜色图例',text:'文字 底色 边框 光柱 地图图标 声音',route:'filter-guide',query:'过滤器 提示 底色 蓝底 青绿 深红 声音 光柱 颜色 边框'}, {title:'物品显示与隐藏判断',text:'按区域、物等、品质、孔位计算匹配链',route:'filter-check',query:'过滤器 显示 隐藏 门票 巨灵币 磨刀石 金币 不显示 5000'},...Object.values(D.learningPages).map(x=>({title:x.title,text:'R37 成长与规则 / '+x.summary,route:'learn/'+x.id,query:x.search+' '+x.sections.map(s=>s.title+' '+s.html.replace(/<[^>]+>/g,' ')).join(' ')})),{title:'新手异界开荒 · Lazy Exile',text:'异界与刷图 / 主树起步、任务推进与三张原图',route:'atlas-starter',query:D.atlasStarter.search},...D.stages.flatMap(p=>p.items.filter(i=>!i.utility).map(i=>({title:i.title+' · '+i.name,text:p.label+' / 装备目标与打造',route:'item/'+i.uid,params:{stage:p.id},query:i.records?.[0]?.en||''}))),...D.variants.map(v=>({title:v.zh,text:v.name+' / Fubgun 异界方案',route:'atlas/'+v.id,query:D.atlasRecords[v.id].search_text})),...D.documents.map(d=>({title:d.title,text:d.group+' / 完整详稿',route:'reference',params:{doc:d.file},query:d.keywords||''})),...Object.entries(D.materials).map(([k,v])=>({title:v.zh,text:v.en+' / 材料与作用',route:'tools/dictionary',params:{q:v.zh}})),...D.augments.map(v=>({title:v.name,text:v.en+' / 强化材料',route:'tools/dictionary',params:{q:v.name}})),{title:'技能组合与宝石升级',text:'人物与技能 / 当前阶段',route:'character',params:{stage:state.stage}},{title:'异界解锁顺序',text:'异界与刷图 / 进入异界',route:'atlas-unlock'},{title:'七套方案怎么选',text:'地图、碑牌、适用条件与配套对照',route:'atlas-choose'}];if(!q)return [data[0],data.find(d=>d.title==='技能组合与宝石升级'),...data.filter(d=>d.route.startsWith('atlas/')).slice(0,4)];q=q.toLowerCase();let seen=new Set();return data.filter(d=>(d.title+' '+d.text+' '+(d.query||'')).toLowerCase().includes(q)).filter(d=>{let k=d.title+d.text;if(seen.has(k))return false;seen.add(k);return true}).slice(0,18)}
let searchResults=[];function updateSearch(){searchResults=searchData($('#search-input').value.trim());$('#search-results').innerHTML=searchResults.map((r,i)=>`<button class="search-result" data-search-result="${i}"><strong>${esc(r.title)}</strong><small>${esc(r.text)}</small></button>`).join('')||'<div class="empty-state">没有匹配结果，试试部位、材料或方案名称。</div>'}
function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';updateSearch();setTimeout(()=>$('#search-input').focus(),0)}
