 if(t.implicit)body+=`<div class="modifier-implicit"><b>底材固有属性：</b>${esc(t.implicit)}<span class="sub">与下方加工词缀分开；不重复占用同一个计数。</span></div>`;
 if(t.raw.length){body+=`<div class="mod-section-label">作者原件已写明的全部属性 <span>${t.raw.length} 项原始描述，不用行数推算前后缀</span></div>`+modTable(t.raw);}
 else if(!t.definitions.length)body+=`<div class="modifier-missing">${slot==='jewels'?'作者没有逐颗珠宝实装；下面按正文列明要找的具体词缀。':(['weapon2','quiver2'].includes(slot)?'原件未单独列这件副装备。不复制主手，也不安排一份假成品。':'原件仅给名称，未提供具体数值词条。')}</div>`;
 if(t.definitions.length)body+=`<div class="mod-section-label">此暗金的完整功能与数值范围 <span>游戏数据补充 · 不是作者实际掷值</span></div>`+modTable(t.definitions);
 if(t.mechanicChoices?.length)body+=`<div class="mod-section-label">六种随机箭矢具体是什么 <span>每支箭只抽到其中一种；下方为功能中文说明</span></div><div class="table-scroll"><table class="modifier-table"><tbody>${t.mechanicChoices.map((x,i)=>`<tr><td>${i+1}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.text)}</td></tr>`).join('')}</tbody></table></div>`;
 if(t.supplement.length)body+=`<div class="mod-section-label">还要补什么／可以换成什么 <span>可选项目不能全部叠成“必需六条”</span></div>`+modTable(t.supplement);
 body+=`<div class="target-bottom"><b>做到什么算够用：</b>${esc(t.closing)}</div></div>`;
 if(!t.readonly&&!t.unique&&!['weapon2','quiver2','jewels','life_flask','mana_flask','charm1','charm2','charm3'].includes(slot))body+=`<div class="whole-set-note"><b>抗性和装备给予的属性怎么分配：</b>整套火焰、冰霜、闪电抗性各补到75%；缺智慧时在一枚戒指或项链解决，力量优先看腰带。余下合法空位再考虑混沌抗性。这里的“补属性”已拆成具体词条，不是佩戴需求。<span class="small muted">作者没有固定每个部位各补多少，不按想象填写三条满值抗性。</span></div>`;
 let wearing=(it?.wear?`<p>使用等级：${it.wear.level||'未提供'}；需要 ${esc(wearText(it.wear))}。这是佩戴要求，不是该装备给予的词缀。</p>`:'<p>佩戴要求以实际物品为准，原件没有提供的值不补猜。</p>');
 body+=expand('佩戴条件、孔位、取得方式与原件出处',wearing+`<p>普通增幅孔：${f?.cap||'不适用'}。${esc(it?.acquire||f?.why||'按实际配置检查。')}</p><p>${esc(it?.alternative||'')}</p><p>原件：${esc(t.sourceFile||'未单独提供')}。</p>`+(t.raw.length?safeLink(it?.sourceUrl||D.equipmentTargetAudit.source,'作者说明'):''));
 const sources=[...new Set([...t.definitions,...t.supplement,...(t.mechanicChoices||[])].map(x=>x.url).filter(Boolean))];if(sources.length)body+=expand('补充属性的出处',sources.map(u=>safeLink(u,u.includes('poe2db')?'物品数据定义':'作者装备说明')).join('　')+'<p class="small muted">原始构筑文件未修改。中文为阅读转述；属性范围与加工目标分开，不把来源未定的数值填满。</p>');
 return body;
